  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also be a self-soothing behavior when they are stressed, injured, or asking for comfort."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even longer because growth and recovery take extra energy."
        },
        {
          question: "Why does my cat knead blankets?",
          answer:
            "Kneading is a comforting behavior that begins in kittenhood. Adult cats may knead soft surfaces when they feel safe, sleepy, or affectionate."
        },
        {
          question: "Should cats drink milk?",
          answer:
            "Many cats are lactose intolerant, so milk can upset their stomachs. Fresh water is the safest everyday drink, and treats should be cat-safe and given sparingly."
        },
        {
          question: "Why do cats need scratching posts?",
          answer:
            "Scratching helps cats stretch, mark territory, and maintain their claws. Providing sturdy posts and pads gives them an appropriate place for this natural behavior."
        }
      ];

      function escapeHtml(value) {
        return value
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#039;");
      }

      function FAQItem({ question, answer, index }) {
        const buttonId = `faq-button-${index}`;
        const panelId = `faq-panel-${index}`;

        return `
          <div class="example">
            <h2 class="question-heading">
              <button
                class="question-button"
                id="${buttonId}"
                type="button"
                aria-expanded="false"
                aria-controls="${panelId}"
              >
                <span>${escapeHtml(question)}</span>
                <span class="indicator" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="${panelId}" aria-labelledby="${buttonId}" hidden>
              <p>${escapeHtml(answer)}</p>
            </div>
          </div>
        `;
      }

      function FAQPage({ items }) {
        return `
          <main id="main-content" class="page-shell">
            <section class="hero" aria-labelledby="page-title">
              <p class="eyebrow">Cat care essentials</p>
              <h1 id="page-title">Curious Cat FAQ</h1>
              <p class="intro">
                Quick, practical answers to common questions about feline habits,
                health basics, and everyday care.
              </p>
            </section>

            <section class="faq-list" aria-label="Frequently asked questions about cats">
              ${items.map((item, index) => FAQItem({ ...item, index })).join("")}
            </section>

            <p class="cat-note">
              If your cat suddenly changes behavior, appetite, grooming, or litter-box habits,
              contact a veterinarian for advice.
            </p>
          </main>
        `;
      }

      function bindDisclosureControls() {
        document.querySelectorAll(".question-button").forEach((button) => {
          const panelId = button.getAttribute("aria-controls");
          const panel = document.getElementById(panelId);

          button.addEventListener("click", () => {
            const isOpen = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!isOpen));
            panel.hidden = isOpen;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
            }
          });
        });
      }

      document.getElementById("root").innerHTML = FAQPage({ items: faqs });
      bindDisclosureControls();
    </script>
  </body>
